define(["jquery"],function($){const open=(element,api)=>{const buttons=Array.from(element.querySelectorAll("[data-answer]"));buttons.forEach(button=>button.addEventListener("click",()=>{buttons.forEach(candidate=>candidate.disabled=true);api.complete({answer:Number(button.dataset.answer)}).then(result=>{if(result.completed){button.classList.add("is-correct");window.setTimeout(()=>api.dismiss(true),900)}else{button.classList.add("is-incorrect");buttons.forEach(candidate=>candidate.disabled=false)}}).catch(()=>buttons.forEach(candidate=>candidate.disabled=false))}))};return{open:open}});